  (* [comment removed for export] *)
  Lemma ki_B : forall (fx : FPState) regs m (keld sy sx cy cx : Z),
    (1 <= keld)%Z -> (keld + 24 < 2 ^ 64)%Z -> (1 <= sy < 2 ^ 31)%Z -> (0 <= sx < 2 ^ 31)%Z -> (0 <= cy < 2 ^ 31)%Z -> (0 <= cx < 2 ^ 31)%Z ->
    store_ok SEGS m (Z_to_bv 64 (keld + 8)) 8 = true ->
    getr regs 10 = Z_to_bv 64 keld -> getr regs 9 = Z_to_bv 64 sy -> getr regs 18 = Z_to_bv 64 sx -> getr regs 19 = Z_to_bv 64 sx ->
    getr regs 20 = Z_to_bv 64 cx -> getr regs 21 = Z_to_bv 64 cy ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2cedc : word) m rom)
                  (@mkst fx regs' (0x2cf20 : word) (wbytes (wbytes m (Z_to_bv 64 (keld + 8)) (w4 (Z_to_bv 64 (sy - 1 - cy)))) (Z_to_bv 64 (keld + 12)) (w4 (Z_to_bv 64 (sx - 1 - cx)))) rom)
      /\ getr regs' 10 = Z_to_bv 64 keld /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 12 = Z_to_bv 64 (4 * sx - 4) /\ getr regs' 19 = Z_to_bv 64 (4 * sx)
      /\ getr regs' 13 = Z_to_bv 64 (-4) /\ getr regs' 14 = Z_to_bv 64 (8 * sy) /\ getr regs' 9 = Z_to_bv 64 sy /\ getr regs' 18 = Z_to_bv 64 sx
