  (* [comment removed for export] *)
  Lemma ki_OH : forall (fx : FPState) regs m (kels keld sy sx i arrs arrd rs rd : Z),
    (1 <= sx < 2 ^ 31)%Z -> (0 <= i < sy)%Z -> (sy < 2 ^ 31)%Z -> (1 <= kels)%Z -> (kels + 24 < 2 ^ 64)%Z -> (1 <= keld)%Z -> (keld + 24 < 2 ^ 64)%Z ->
    (0 <= arrs)%Z -> (arrs + 8 * sy < 2 ^ 64)%Z -> (0 <= arrd)%Z -> (arrd + 8 * sy < 2 ^ 64)%Z -> (0 <= rs < 2 ^ 64)%Z -> (0 <= rd < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (kels + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 arrs)) ->
    rdn SEGS m (Z_to_bv 64 (keld + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 arrd)) ->
    rdn SEGS m (Z_to_bv 64 (arrs + 8 * (sy - 1 - i))) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 rs)) ->
    rdn SEGS m (Z_to_bv 64 (arrd + 8 * i)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 rd)) ->
    getr regs 18 = Z_to_bv 64 sx -> getr regs 8 = Z_to_bv 64 kels -> getr regs 10 = Z_to_bv 64 keld -> getr regs 11 = Z_to_bv 64 i ->
    getr regs 14 = Z_to_bv 64 (8 * sy) -> getr regs 12 = Z_to_bv 64 (4 * sx - 4) -> getr regs 13 = Z_to_bv 64 (-4) ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2cf20 : word) m rom) (@mkst fx regs' (0x2cf54 : word) m rom)
      /\ getr regs' 15 = Z_to_bv 64 rd /\ getr regs' 16 = Z_to_bv 64 (rs + (4 * sx - 4)) /\ getr regs' 17 = Z_to_bv 64 (rs - 4) /\ getr regs' 5 = Z_to_bv 64 rs
      /\ regs_agree (fun x => In x [5; 15; 16; 17]%list) regs regs'.
Proof.
