  (* [comment removed for export] *)
  Lemma ki_I : forall (last : bool) fr cs regs m (p q e : Z) (bs : list byte),
    (4 <= p)%Z -> (p + 4 <= 2 ^ 64)%Z -> (0 <= q)%Z -> (q + 8 <= 2 ^ 64)%Z -> (0 <= e < 2 ^ 64)%Z -> (if last then p - 4 = e else p - 4 <> e)%Z ->
    rdn SEGS m (Z_to_bv 64 p) 4 = Some bs -> store_ok SEGS m (Z_to_bv 64 q) 4 = true ->
    getr regs 16 = Z_to_bv 64 p -> getr regs 15 = Z_to_bv 64 q -> getr regs 17 = Z_to_bv 64 e ->
    exists regs' (v : word),
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2cf54 : word) m rom)
                  (@mkst (mkFP (bvmap_set 15 v fr) cs) regs' (if last then (0x2cf18 : word) else (0x2cf54 : word))
                         (wbytes m (Z_to_bv 64 q) (Z_to_le_bytes 4 (u (low32 v)))) rom)
      /\ getr regs' 16 = Z_to_bv 64 (p - 4) /\ getr regs' 15 = Z_to_bv 64 (q + 4) /\ getr regs' 17 = Z_to_bv 64 e
      /\ regs_agree (fun x => In x [15; 16]%list) regs regs'.
Proof.
