  (* [comment removed for export] *)
  Lemma ki_ON : forall (fx : FPState) (last : bool) regs m (i sy : Z),
    (0 <= i < sy)%Z -> (sy < 2 ^ 31)%Z -> (if last then i + 1 = sy else i + 1 < sy)%Z ->
    getr regs 11 = Z_to_bv 64 i -> getr regs 9 = Z_to_bv 64 sy ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2cf18 : word) m rom) (@mkst fx regs' (if last then (0x2cfdc : word) else (0x2cf20 : word)) m rom)
      /\ getr regs' 11 = Z_to_bv 64 (i + 1)
      /\ regs_agree (fun x => In x [11]%list) regs regs'.
